import React, { useRef } from "react";
import "./TestimonialGrid.css";

export default function TestimonialGrid({ videos = [] }) {
  const refs = useRef([]);

  // Pause all other videos when one plays
  const pauseAll = (exceptIndex = -1) => {
    refs.current.forEach((vid, i) => {
      if (vid && i !== exceptIndex) {
        vid.pause();
      }
    });
  };

  const handleClick = (i) => {
    const vid = refs.current[i];
    if (!vid) return;

    // browser-safe toggle play/pause
    if (vid.paused) {
      pauseAll(i);
      vid.muted = false; // unmute when user clicks
      vid.play().catch((err) => console.log("Play blocked:", err));
    } else {
      vid.pause();
    }
  };

  return (
    <section className="testimonial-section">
      <h3 className="testimonial-title">Testimonial Videos</h3>
      <div className="testimonial-grid">
        {videos.map((src, i) => (
          <div
            className="testimonial-card"
            key={i}
            onClick={() => handleClick(i)}
          >
            <video
              ref={(el) => (refs.current[i] = el)}
              src={src}
              className="testimonial-video"
              preload="metadata"
              muted
              playsInline
              loop={false}
              controls
              onPlay={() => pauseAll(i)}
              onLoadedData={(e) => {
                // Ensure full brightness
                e.target.style.filter = "brightness(1)";
              }}
              onCanPlay={(e) => {
                // Force refresh to fix dim bug
                e.target.style.opacity = 1;
              }}
            />
          </div>
        ))}
      </div>
    </section>
  );
}
